param()
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
$root=Split-Path -Parent $PSScriptRoot
Import-Module (Join-Path $PSScriptRoot 'ConformanceReviewedSources.psm1')
Import-Module (Join-Path $PSScriptRoot 'ConformanceTargetMatrix.psm1')
Import-Module (Join-Path $PSScriptRoot 'ConformanceAggregateReplay.psm1')
Import-Module (Join-Path $PSScriptRoot 'ConformanceRunner.psm1')
Import-Module (Join-Path $PSScriptRoot 'ConformanceInventory.psm1')
Import-Module (Join-Path $PSScriptRoot 'TargetWitnessPolicy.psm1')
$base='tests/conformance/targets/remaining-upstream-compatibility/'
$temporary=Join-Path $root ('reports/reviewed-source-integration/'+[guid]::NewGuid().ToString('N'))
[void][IO.Directory]::CreateDirectory($temporary)
$inventory=Test-ConformanceInventory -Root $root -TargetPolicy remaining-upstream-compatibility
$resolved=@{};foreach($entry in $inventory.Exclusions){$resolved[$entry.id]=$entry}
$policy=(Get-FileHash (Join-Path $root 'tests/conformance/targets/remaining-upstream-compatibility.exclusions.json')).Hash.ToLowerInvariant()
$suite=Get-Content (Join-Path $root 'tests/conformance/suite.json') -Raw|ConvertFrom-Json -AsHashtable -Depth 48
$script:cases=0
function Case($Description,[scriptblock]$Action){&$Action;$script:cases++;Write-Output "SOURCE INTEGRATION PASS: $Description"}
function Reject([scriptblock]$Action,$Pattern){$failure=$null;try{&$Action|Out-Null}catch{$failure=$_.Exception.Message}
    if($null -eq $failure -or $failure -notmatch $Pattern){throw "Wrong source integration rejection: $failure; expected $Pattern"}}
function Save($Path,$Value){[IO.File]::WriteAllText($Path,(ConvertTo-Json -InputObject $Value -Depth 64).Replace("`r`n","`n")+"`n",[Text.UTF8Encoding]::new($false));return (Get-FileHash $Path).Hash.ToLowerInvariant()}
function New-Fixture($Name){
    $manifest=$base+$Name;$m=Get-Content (Join-Path $root $manifest) -Raw|ConvertFrom-Json -AsHashtable -Depth 64
    $replay=Get-TargetReviewedSourceReplay -Root $root -Specification $m -Implementation Ada -Configuration upstream-test -PolicySha256 $policy -ResolvedExclusions $resolved
    $out=Join-Path $temporary ([guid]::NewGuid().ToString('N')+'.lua');[IO.File]::WriteAllBytes($out,$replay.bytes)
    # This fixture has no process or runtime observations. Its synthetic label
    # is explicit; only the private source-byte reconciliation routine runs.
    $identity=@{manifest_path=$manifest;manifest_sha256=(Get-FileHash (Join-Path $root $manifest)).Hash.ToLowerInvariant();
        output=$out;output_sha256=$replay.sha256;review_status='accepted';diagnostic_only=$false}
    $file=[IO.Path]::GetFileName($m.source)
    $report=@{synthetic_fixture=$true;execution_disposition=$replay.disposition;reviewed_source=$identity;
        target='Ada';requested_configuration='upstream-test';exclusion_policy_sha256=$policy;excluded_obligations=@($replay.excluded_obligations)}
    $contract=@{reviewed_source_manifest_sha256=$identity.manifest_sha256;exclusion_policy_sha256=$policy;executed_sha256=$replay.sha256;disposition=$replay.disposition}
    return @{mapping=$m;manifest=$manifest;report=$report;contract=$contract;entry=@{operation=('file:'+$file)}}
}
function Reconcile($f){& (Get-Module ConformanceTargetMatrix) {
    param($r,$a,$f,$e)
    Assert-TargetTransformReplay -Root $r -ArtifactRoot $a -Report $f.report -Entry $f.entry -Contract $f.contract -ResolvedExclusions $e
} $root $root $f $resolved}
foreach($name in @('api-private-bound-and-userdata-lifetimes.composite.json','calls-undump-constant-pool.equivalent.json','memerr-verifier-allocation.equivalent.json')){
    Case "synthetic File source identity reconciles exact approved $name bytes without execution" {$f=New-Fixture $name;Reconcile $f}
}
Case 'changed generated bytes cannot inherit the exact reviewed source contract' {
    $f=New-Fixture 'calls-undump-constant-pool.equivalent.json';[IO.File]::AppendAllText($f.report.reviewed_source.output,'-- changed')
    $f.report.reviewed_source.output_sha256=(Get-FileHash $f.report.reviewed_source.output).Hash.ToLowerInvariant()
    Reject {Reconcile $f} 'executed transform bytes'
}
Case 'a different reviewed manifest cannot borrow the operation contract' {$f=New-Fixture 'calls-undump-constant-pool.equivalent.json';$f.contract.reviewed_source_manifest_sha256='0'*64;Reject {Reconcile $f} 'reviewed source contract'}
Case 'API composition cannot omit its exact private child exclusion' {$f=New-Fixture 'api-private-bound-and-userdata-lifetimes.composite.json';$f.report.excluded_obligations=@();Reject {Reconcile $f} 'exact exclusion set'}
Case 'source-selection contract must retain the current reviewed policy' {$f=New-Fixture 'calls-undump-constant-pool.equivalent.json';$f.contract.exclusion_policy_sha256='0'*64;Reject {Reconcile $f} 'reviewed source contract'}
Case 'native original reports cannot select Ada source equivalents' {$f=New-Fixture 'calls-undump-constant-pool.equivalent.json';$f.report.target='ReferenceC';Reject {Reconcile $f} 'instrumented Ada'}
Case 'a report cannot select an equivalent for another original primary' {$f=New-Fixture 'calls-undump-constant-pool.equivalent.json';$f.entry.operation='file:api.lua';Reject {Reconcile $f} 'another original source'}
Case 'the legacy equivalent identity cannot bypass bounded target selection' {
    $f=New-Fixture 'calls-undump-constant-pool.equivalent.json';$f.report.equivalent=$f.report.reviewed_source;$f.report.reviewed_source=$null
    Reject {Reconcile $f} 'reviewed_source report identity'
}

function New-Aggregate {
    $selections=@(foreach($name in @('api-private-bound-and-userdata-lifetimes.composite.json','calls-undump-constant-pool.equivalent.json','memerr-verifier-allocation.equivalent.json')){
        $p=$base+$name;$m=Get-Content (Join-Path $root $p) -Raw|ConvertFrom-Json -AsHashtable -Depth 64
        @{source=[IO.Path]::GetFileName($m.source);kind='reviewed-source';manifest=@{path=$p;sha256=(Get-FileHash (Join-Path $root $p)).Hash.ToLowerInvariant()}}
    })
    $m=@{schema_version=1;kind='target-aggregate-replay';id='synthetic-reviewed-selection';target='remaining-upstream-compatibility';
        reference_revision=$suite.reference_revision;configuration='upstream-test';implementation='Ada';platform='windows';
        original_sources=@($suite.files|ForEach-Object{@{path=$_.path;sha256=$_.sha256}});selections=$selections;
        synthetic_fixture=$true;runtime_acceptance=$false;coverage_authority=$false;
        review=@{status='accepted';author='synthetic-author';reviewer='synthetic-reviewer';artifact=$null;artifact_sha256=$null}}
    $narrative=Join-Path $temporary ([guid]::NewGuid().ToString('N')+'.json')
    $nh=Save $narrative @{reviewer='synthetic-reviewer';decision='accepted';replay_id=$m.id;synthetic_fixture=$true;
        preserves_aggregate_protocol=$true;preserves_public_assertions=$true;source_preservation='Synthetic selection binding fixture, no actual aggregate approval or execution.'}
    $approval=Join-Path $temporary ([guid]::NewGuid().ToString('N')+'.json')
    $ah=Save $approval @{schema_version=1;kind='target-aggregate-replay-approval';author='synthetic-author';reviewer='synthetic-reviewer';
        decision='accepted';synthetic_fixture=$true;selection_sha256=(Get-TargetWitnessPayloadHash (Get-TargetAggregateClaims $m));
        review_evidence=@{path=[IO.Path]::GetRelativePath($root,$narrative).Replace('\','/');sha256=$nh}}
    $m.review.artifact=[IO.Path]::GetRelativePath($root,$approval).Replace('\','/');$m.review.artifact_sha256=$ah
    return $m
}
function Aggregate($m,[switch]$Synthetic){Get-TargetAggregateReplay -Root $root -Specification $m -Suite $suite -Configuration upstream-test -Implementation Ada -Platform windows -PolicySha256 $policy -ResolvedExclusions $resolved -AllowSynthetic:$Synthetic}
Case 'synthetic aggregate selection retains all34 originals and independently replays all3 actual source decisions' {
    $m=New-Aggregate;$r=Aggregate $m -Synthetic
    if($r.expected_sources.Count -ne 34 -or $r.transforms.Count -ne 3 -or $r.excluded_obligations.Count -ne 1 -or $r.runtime_acceptance -or $r.coverage_authority){throw 'Aggregate source selection lost original obligations or invented authority'}
}
Case 'synthetic aggregate approval cannot authorize an actual source tree' {$m=New-Aggregate;Reject {Aggregate $m} 'Invalid aggregate replay'}
Case 'source inner approval does not approve its aggregate selection' {$m=New-Aggregate;$m.review.status='pending';Reject {Aggregate $m -Synthetic} 'independent source selection review'}
Case 'generic aggregate equivalent cannot bypass bounded source selection' {$m=New-Aggregate;$m.selections[1].kind='equivalent';Reject {Aggregate $m -Synthetic} 'reviewed-source selection'}
Case 'aggregate source selection cannot apply two independent patches sequentially to the same original' {$m=New-Aggregate;$m.selections+=@($m.selections[0]);Reject {Aggregate $m -Synthetic} 'unknown duplicate'}
Case 'missing API source operation cannot erase its required private exclusion linkage' {$m=New-Aggregate;$m.selections=@($m.selections|Where-Object source -CNE api.lua);Reject {Aggregate $m -Synthetic} 'exactly its approved exclusions'}
Case 'configured native caller cannot select a reviewed Ada File source' {
    $p=Invoke-ConformanceProcess -Executable (Get-Command pwsh).Source -Arguments @('-NoProfile','-File',(Join-Path $PSScriptRoot 'run-conformance.ps1'),
        '-Target','ReferenceC','-Configuration','upstream-test','-Mode','File','-File','calls.lua','-TargetPolicy','remaining-upstream-compatibility',
        '-ReviewedSourceManifest',(Join-Path $root ($base+'calls-undump-constant-pool.equivalent.json'))) -Directory $root -OutputPrefix (Join-Path $temporary 'wrong-native-mode') -TimeoutSeconds 60
    if($p.exit_code -eq 0 -or [IO.File]::ReadAllText($p.stderr_path) -notmatch 'separate instrumented Ada File target'){throw 'Wrong-role runner reached adapted execution'}
}
Write-Output "PASS: $script:cases reviewed File/Aggregate source integration regressions; synthetic report/outer review fixtures, no Lua execution or acceptance"
